import sys
import time

INF=100000000
MATE=100000
VAL={'p':100,'n':320,'b':330,'r':500,'q':900,'k':20000}
PROM={1:'n',2:'b',3:'r',4:'q'}

def attacked(p,sq,by):
    if not 0<=sq<64:return False
    b=p.b;r,f=divmod(sq,8)
    rr=r-1 if by==0 else r+1
    pawn='P' if by==0 else 'p'
    if 0<=rr<8:
        for ff in (f-1,f+1):
            if 0<=ff<8 and b[rr*8+ff]==pawn:return True
    knight='N' if by==0 else 'n'
    for dr,df in ((2,1),(2,-1),(-2,1),(-2,-1),(1,2),(1,-2),(-1,2),(-1,-2)):
        x,y=r+dr,f+df
        if 0<=x<8 and 0<=y<8 and b[x*8+y]==knight:return True
    king='K' if by==0 else 'k'
    for dr in (-1,0,1):
        for df in (-1,0,1):
            if dr or df:
                x,y=r+dr,f+df
                if 0<=x<8 and 0<=y<8 and b[x*8+y]==king:return True
    for dr,df,ch in ((1,0,'rq'),(-1,0,'rq'),(0,1,'rq'),(0,-1,'rq'),(1,1,'bq'),(1,-1,'bq'),(-1,1,'bq'),(-1,-1,'bq')):
        x,y=r+dr,f+df
        while 0<=x<8 and 0<=y<8:
            z=b[x*8+y]
            if z!='.':
                if z.isupper()==(by==0) and z.lower() in ch:return True
                break
            x+=dr;y+=df
    return False

def king(p,side):
    k='K' if side==0 else 'k'
    for i,x in enumerate(p.b):
        if x==k:return i
    return -1

def enc(a,z,pr=0,fl=0):return a|(z<<6)|(pr<<12)|(fl<<16)

class Delta:
    def __init__(self,p):
        self.squares=[];self.side=p.side;self.cast=p.cast;self.ep=p.ep
        self.half=p.half;self.full=p.full;self.key=None

class Position:
    def __init__(self,b,side,cast,ep,half,full):
        self.b=b;self.side=side;self.cast=cast;self.ep=ep;self.half=half;self.full=full
        self.rep={};self.rep[self.key()]=1
    @classmethod
    def fen(cls,s):
        a=s.split();b=['.']*64
        for ri,row in enumerate(a[0].split('/')):
            sq=(7-ri)*8
            for x in row:
                if x.isdigit():sq+=int(x)
                else:b[sq]=x;sq+=1
        c=0
        for i,x in enumerate('KQkq'):
            if x in a[2]:c|=1<<i
        ep=-1
        if a[3]!='-':ep=ord(a[3][0])-97+8*(int(a[3][1])-1)
        return cls(b,0 if a[1]=='w' else 1,c,ep,int(a[4]),int(a[5]))
    @classmethod
    def start(cls):return cls.fen('rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1')
    def key(self):return (''.join(self.b),self.side,self.cast,effective_ep(self))

def set_square(p,d,sq,v):
    if p.b[sq]==v:return
    for x,_ in d.squares:
        if x==sq:p.b[sq]=v;return
    d.squares.append((sq,p.b[sq]));p.b[sq]=v

def make(p,m):
    a=m&63;z=(m>>6)&63;pr=(m>>12)&15;fl=m>>16
    d=Delta(p);pc=p.b[a];cap=p.b[z]
    set_square(p,d,a,'.')
    if fl&2:
        v=z-8 if pc.isupper() else z+8
        cap=p.b[v];set_square(p,d,v,'.')
    set_square(p,d,z,pc)
    if fl&1:
        if z==6:set_square(p,d,7,'.');set_square(p,d,5,'R')
        elif z==2:set_square(p,d,0,'.');set_square(p,d,3,'R')
        elif z==62:set_square(p,d,63,'.');set_square(p,d,61,'r')
        elif z==58:set_square(p,d,56,'.');set_square(p,d,59,'r')
    if pr:set_square(p,d,z,('NBRQ' if pc.isupper() else 'nbrq')[pr-1])
    c=p.cast
    if pc=='K':c&=12
    elif pc=='k':c&=3
    if a==0 or z==0:c&=~2
    if a==7 or z==7:c&=~1
    if a==56 or z==56:c&=~8
    if a==63 or z==63:c&=~4
    p.cast=c;p.ep=(a+z)//2 if pc.lower()=='p' and abs(z-a)==16 else -1
    p.half=0 if pc.lower()=='p' or cap!='.' else p.half+1
    if p.side:p.full+=1
    p.side^=1
    d.key=p.key();p.rep[d.key]=p.rep.get(d.key,0)+1
    return d

def unmake(p,d):
    n=p.rep.get(d.key,0)
    if n<=1:p.rep.pop(d.key,None)
    else:p.rep[d.key]=n-1
    for sq,old in reversed(d.squares):p.b[sq]=old
    p.side=d.side;p.cast=d.cast;p.ep=d.ep;p.half=d.half;p.full=d.full

def effective_ep(p):
    e=p.ep
    if not 0<=e<64 or p.b[e]!='.':return -1
    side=p.side;r,f=divmod(e,8);v=e-8 if side==0 else e+8
    if not 0<=v<64 or p.b[v]!=('p' if side==0 else 'P'):return -1
    pawn='P' if side==0 else 'p'
    for ff in (f-1,f+1):
        if 0<=ff<8 and p.b[r*8+ff]==pawn:
            d=make(p,enc(r*8+ff,e,0,2))
            try:ok=not attacked(p,king(p,side),side^1)
            finally:unmake(p,d)
            if ok:return e
    return -1

def pseudo(p,captures=False,tick=None):
    if tick:tick()
    b=p.b;white=p.side==0;out=[]
    def add(a,z,pr=0,fl=0,cap=False):
        if not captures or cap or pr:out.append(enc(a,z,pr,fl))
    for s,pc in enumerate(b):
        if tick and s&7==0:tick()
        if pc=='.' or pc.isupper()!=white:continue
        r,f=divmod(s,8);t=pc.lower()
        if t=='p':
            d=8 if white else -8;z=s+d
            prom=0<=z<64 and z//8==(7 if white else 0)
            if 0<=z<64 and b[z]=='.':
                if prom:
                    for q in (4,3,2,1):add(s,z,q)
                else:add(s,z)
                if not captures and r==(1 if white else 6) and b[s+2*d]=='.':add(s,s+2*d,0,4)
            for df in (-1,1):
                if not 0<=f+df<8:continue
                z=s+d+df
                if not 0<=z<64:continue
                x=b[z]
                if x!='.' and x.isupper()!=white:
                    if z//8==(7 if white else 0):
                        for q in (4,3,2,1):add(s,z,q,0,True)
                    else:add(s,z,0,0,True)
                elif z==p.ep:
                    v=z-8 if white else z+8
                    if b[z]=='.' and 0<=v<64 and b[v]==('p' if white else 'P'):add(s,z,0,2,True)
        elif t=='n':
            for dr,df in ((2,1),(2,-1),(-2,1),(-2,-1),(1,2),(1,-2),(-1,2),(-1,-2)):
                x,y=r+dr,f+df
                if 0<=x<8 and 0<=y<8:
                    z=x*8+y
                    if b[z]=='.' or b[z].isupper()!=white:add(s,z,0,0,b[z]!='.')
        elif t in 'brq':
            ds=[]
            if t in 'bq':ds+=((1,1),(1,-1),(-1,1),(-1,-1))
            if t in 'rq':ds+=((1,0),(-1,0),(0,1),(0,-1))
            for dr,df in ds:
                x,y=r+dr,f+df
                while 0<=x<8 and 0<=y<8:
                    z=x*8+y
                    if b[z]=='.':add(s,z)
                    else:
                        if b[z].isupper()!=white:add(s,z,0,0,True)
                        break
                    x+=dr;y+=df
        else:
            for dr in (-1,0,1):
                for df in (-1,0,1):
                    if dr or df:
                        x,y=r+dr,f+df
                        if 0<=x<8 and 0<=y<8:
                            z=x*8+y
                            if b[z]=='.' or b[z].isupper()!=white:add(s,z,0,0,b[z]!='.')
            if not captures and s==(4 if white else 60) and not attacked(p,s,p.side^1):
                if white and p.cast&1 and b[5]==b[6]=='.' and b[7]=='R' and not attacked(p,5,1) and not attacked(p,6,1):add(s,6,0,1)
                if white and p.cast&2 and b[1]==b[2]==b[3]=='.' and b[0]=='R' and not attacked(p,3,1) and not attacked(p,2,1):add(s,2,0,1)
                if not white and p.cast&4 and b[61]==b[62]=='.' and b[63]=='r' and not attacked(p,61,0) and not attacked(p,62,0):add(s,62,0,1)
                if not white and p.cast&8 and b[57]==b[58]==b[59]=='.' and b[56]=='r' and not attacked(p,59,0) and not attacked(p,58,0):add(s,58,0,1)
    return out

def legal(p,captures=False,tick=None):
    out=[];side=p.side
    for m in pseudo(p,captures,tick):
        if tick:tick()
        if p.b[(m>>6)&63].lower()=='k':continue
        d=make(p,m)
        try:
            if not attacked(p,king(p,side),side^1):out.append(m)
        finally:unmake(p,d)
    return out

def notation(m):
    a=m&63;z=(m>>6)&63;pr=(m>>12)&15
    return 'abcdefgh'[a&7]+str(a//8+1)+'abcdefgh'[z&7]+str(z//8+1)+(PROM[pr] if pr else '')

def insufficient(p):
    x=[]
    for sq,pc in enumerate(p.b):
        if pc!='.' and pc.lower() not in ('k','p'):
            if pc.lower() in ('q','r'):return False
            x.append((sq,pc.lower()))
    if not x:return True
    if len(x)==1:return x[0][1] in ('b','n')
    if all(t=='b' for _,t in x):return len({(s//8+s%8)&1 for s,_ in x})==1
    return False

class Engine:
    def __init__(self):
        self.pos=Position.start();self.root_moves=[];self.tt={};self.history={};self.killers={};self.nodes=0;self.deadline=0;self.refresh_root()
    def refresh_root(self):self.root_moves=legal(self.pos)
    def evaluate(self,p):
        score=0;phase=0;wp=[0]*8;bp=[0]*8;wb=bb=0;pawns=0
        for pc in p.b:
            if pc!='.' and pc.lower() not in ('p','k'):phase+=VAL[pc.lower()]
        for s,pc in enumerate(p.b):
            if pc=='.':continue
            t=pc.lower();sg=1 if pc.isupper() else -1;score+=sg*VAL[t];r,f=divmod(s,8);rr=r if sg==1 else 7-r;center=7-abs(2*f-7)-abs(2*rr-7)
            if t=='p':
                pawns+=1;(wp if sg==1 else bp)[f]+=1;score+=sg*(rr*10+center*2);passed=True
                for r2 in (range(r+1,8) if sg==1 else range(r-1,-1,-1)):
                    for f2 in (f-1,f,f+1):
                        if 0<=f2<8 and p.b[r2*8+f2]==('p' if sg==1 else 'P'):passed=False
                if passed:score+=sg*(18+rr*8)
            elif t=='n':score+=sg*center*10
            elif t=='b':score+=sg*center*5;wb+=sg==1;bb+=sg==-1
            elif t=='r':score+=sg*(rr*3+(5 if f in (3,4) else 0));score+=sg*12 if (wp if sg==1 else bp)[f]==0 else 0
            elif t=='q':score+=sg*center*2
            elif phase>2600:score+=sg*(-center*3)
            else:score+=sg*center*10
        if wb>=2:score+=30
        if bb>=2:score-=30
        for n in wp:score-=max(0,n-1)*10
        for n in bp:score+=max(0,n-1)*10
        for f,n in enumerate(wp):
            if n and (f==0 or wp[f-1]==0) and (f==7 or wp[f+1]==0):score-=10*n
        for f,n in enumerate(bp):
            if n and (f==0 or bp[f-1]==0) and (f==7 or bp[f+1]==0):score+=10*n
        if pawns==0 and (phase==0 or phase==320 or (phase==330 and wb+bb==1)):return 0
        return score if p.side==0 else -score
    def check_time(self):
        self.nodes+=1
        if self.nodes&31==0 and time.perf_counter()>=self.deadline:raise TimeoutError
    def mscore(self,p,m,tt,ply):
        a=m&63;z=(m>>6)&63;pr=(m>>12)&15;fl=m>>16;sc=10000000 if m==tt else 0;cap=p.b[z]
        if fl&2:cap='p'
        if cap!='.':sc+=1000000+VAL[cap.lower()]*10-VAL[p.b[a].lower()]
        if pr:sc+=800000+pr*10000
        if self.killers.get(ply)==m:sc+=500000
        sc+=self.history.get((p.side,a,z),0)
        if fl&1:sc+=100
        return sc
    def draw(self,p):return p.half>=100 or p.rep.get(p.key(),0)>=3 or insufficient(p)
    def qsearch(self,p,alpha,beta,ply):
        self.check_time();checked=attacked(p,king(p,p.side),p.side^1);stand=self.evaluate(p) if not checked else -INF;ms=legal(p,False if checked else True,self.check_time)
        if not ms:return -MATE+ply if checked else stand
        if self.draw(p):return 0
        if ply>=12:return stand
        if not checked:
            if stand>=beta:return stand
            if stand>alpha:alpha=stand
        ms.sort(key=lambda m:self.mscore(p,m,-1,ply),reverse=True)
        for m in ms:
            d=make(p,m)
            try:sc=-self.qsearch(p,-beta,-alpha,ply+1)
            finally:unmake(p,d)
            if sc>=beta:return sc
            if sc>alpha:alpha=sc
        return alpha
    def search(self,p,depth,alpha,beta,ply):
        self.check_time()
        if depth<=0:return self.qsearch(p,alpha,beta,ply)
        key=p.key();orig=alpha;oldbeta=beta;ent=self.tt.get(key);tt=-1
        if ent:
            tt=ent[4]
            if ent[0]>=depth:
                sc=ent[1]
                if ent[2]==0:return sc
                if ent[2]==1:alpha=max(alpha,sc)
                elif ent[2]==2:beta=min(beta,sc)
                if alpha>=beta:return sc
        ms=legal(p,False,self.check_time)
        if not ms:return -MATE+ply if attacked(p,king(p,p.side),p.side^1) else 0
        if self.draw(p):return 0
        ms.sort(key=lambda m:self.mscore(p,m,tt,ply),reverse=True);best=-INF;bestm=ms[0]
        for m in ms:
            self.check_time();d=make(p,m)
            try:
                nd=depth-1
                if depth<=2 and attacked(p,king(p,p.side),p.side^1):nd+=1
                sc=-self.search(p,nd,-beta,-alpha,ply+1)
            finally:unmake(p,d)
            if sc>best:best=sc;bestm=m
            if sc>alpha:alpha=sc
            if alpha>=beta:
                if p.b[m&63].lower()!='p' and p.b[(m>>6)&63]=='.' and not ((m>>12)&15):
                    self.killers[ply]=m;k=(p.side,m&63,(m>>6)&63);self.history[k]=min(10000,self.history.get(k,0)+depth*depth)
                break
        flag=2 if best<=orig else 1 if best>=oldbeta else 0
        self.tt[key]=(depth,best,flag,ply,bestm)
        if len(self.tt)>180000:self.tt.clear()
        return best
    def root(self,p,ms,depth):
        ms=ms[:];ms.sort(key=lambda m:self.mscore(p,m,-1,0),reverse=True);alpha=-INF;best=-INF;bm=ms[0]
        for m in ms:
            self.check_time();d=make(p,m)
            try:sc=-self.search(p,depth-1,-INF,-alpha,1)
            finally:unmake(p,d)
            if sc>best:best=sc;bm=m
            if sc>alpha:alpha=sc
        return best,bm
    def think(self,millis):
        moves=self.root_moves[:]
